"""Samodzielne makiety wybranego kierunku; nie modyfikuje aplikacji ani galerii opcji."""
from pathlib import Path
import json
base=Path(__file__).with_name('t14-build-mockups.py')
# Reużywamy wyłącznie definicje, bez części zapisującej pierwotną galerię.
namespace={'__file__':str(base)}
exec(compile(base.read_text().split("for v in ['focus','table','cards']:",1)[0],str(base),'exec'),namespace)
out=base.parent
ico=namespace['ico']; frame=namespace['frame']; header=namespace['header']; nav=namespace['nav']; css=namespace['css']
plans=[{'name':'Fundament siły','caption':'Plan A/B','description':'Siła podstawowa i akcesoria'}, {'name':'Siła — kolejny blok','caption':'Plan A/B','description':'Kolejna wersja pracy nad siłą'}, {'name':'Plan uzupełniający','caption':'Plan A/B','description':'Drugi zestaw do wyboru'}]
extra_css='''
.focus .body:has(.plan-version) .sectionhead{margin-top:8px}.focus .exercise{margin-bottom:7px}.focus .bottomnav .ico{width:21px;height:21px}.plantrack{display:flex;position:relative;gap:12px;overflow-x:auto;scroll-snap-type:x mandatory;scroll-padding:0 18px;margin:0 -18px;padding:0 18px;scrollbar-width:none;overscroll-behavior-x:contain}.plantrack::-webkit-scrollbar{display:none}.planslide{flex:0 0 100%;scroll-snap-align:start;background:var(--forest);color:white;border-radius:16px;padding:20px;min-width:0}.planslide h2{font-size:23px;line-height:1.2;min-height:28px}.planslide .desc{font-size:13px;color:#d6e4d9;margin:8px 0 14px}.planslide .planmeta{font-size:12px;color:#d6e4d9;margin-bottom:18px}.carouselbar{display:flex;align-items:center;gap:8px;margin:10px 0 12px}.carouselbar .iconbtn{border:1px solid var(--line);border-radius:10px;background:white}.carouselbar button:disabled{opacity:.35;cursor:default}.position{flex:1;min-width:0;font-size:12px;text-align:center;color:var(--muted);line-height:1.5}.position strong{display:block;color:var(--forest);font-size:13px}.dots{display:flex;justify-content:center;gap:3px;margin-top:-4px}.dots button{width:44px;height:44px;display:grid;place-items:center;border-radius:8px}.dots span{height:7px;width:7px;border-radius:50%;background:#a9b6a3}.dots button[aria-current=true] span{background:var(--forest);width:20px;border-radius:5px}.plan-name{overflow-wrap:anywhere}.plans-note{font-size:12px;color:var(--muted);margin-top:16px}.goal .sub{font-size:13px}.facts strong{overflow-wrap:anywhere}
'''
def plans_content(pi):
 slides=''
 for i,p in enumerate(plans):
  slides+=f'<section class="planslide" aria-label="{i+1} z 3: {p["name"]}"><h2>{p["name"]}</h2><p class="desc">{p["caption"]} · {p["description"]}</p><p class="planmeta">2 treningi · 8 ćwiczeń</p><button class="btn light" data-open="{i}">Otwórz plan {ico("chevron")}</button></section>'
 dots=''.join(f'<button data-slide="{i}" aria-label="Pokaż plan {i+1}: {p["name"]}" aria-current="{str(i==pi).lower()}"><span></span></button>' for i,p in enumerate(plans))
 rows=''.join(f'<button class="dayrow" data-session="{s}" data-go="plan"><span class="dayletter">{s.upper()}</span><span class="daycopy"><strong>{name}</strong><small>4 ćwiczenia · {focus}</small></span>{ico("chevron","chev")}</button>' for s,name,focus in [('a','Siła podstawowa','nogi, klatka, plecy'),('b','Siła i akcesoria','tył ciała, barki, core')])
 return '<div class="headline"><div><h1>Twoje plany</h1><p class="sub">Przesuń w lewo lub w prawo, aby wybrać plan.</p></div></div><div class="plantrack" role="region" aria-roledescription="karuzela" aria-label="Twoje plany" tabindex="0">'+slides+'</div><div class="carouselbar"><button class="iconbtn" id="prev" aria-label="Poprzedni plan">'+ico('back')+'</button><p class="position" id="position" role="status" aria-live="polite"></p><button class="iconbtn" id="next" aria-label="Następny plan">'+ico('chevron')+'</button></div><div class="dots" aria-label="Wybierz plan">'+dots+'</div><div class="sectionhead"><h2>Treningi w planie</h2></div>'+rows+'<div class="split-actions"><button class="btn secondary" data-info="Import pozostaje w istniejącym przepływie.">'+ico('upload')+' Importuj</button><button class="btn secondary" data-info="Tworzenie planu pozostaje w istniejącym edytorze.">'+ico('plus')+' Nowy plan</button></div>'
inner_script='''<script>
const PLAN_NAMES=__NAMES__;let selectedPlan=__PLAN__,scrollTimer;const track=document.querySelector('.plantrack');
function tell(data){parent.postMessage({selectedMock:true,plan:selectedPlan,...data},'*')}
function update(index,notify=true){selectedPlan=Math.max(0,Math.min(PLAN_NAMES.length-1,index));let position=document.getElementById('position');if(position){position.innerHTML='<strong>Plan '+(selectedPlan+1)+' z '+PLAN_NAMES.length+'</strong>'+PLAN_NAMES[selectedPlan];document.getElementById('prev').disabled=selectedPlan===0;document.getElementById('next').disabled=selectedPlan===PLAN_NAMES.length-1;document.querySelectorAll('[data-slide]').forEach(b=>b.setAttribute('aria-current',Number(b.dataset.slide)===selectedPlan))}if(notify)tell({selectPlan:true})}
function move(index){let target=Math.max(0,Math.min(PLAN_NAMES.length-1,index));update(target);const slides=track.querySelectorAll('.planslide');track.scrollTo({left:slides[target].offsetLeft-slides[0].offsetLeft,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'})}
if(track){update(selectedPlan,false);requestAnimationFrame(()=>{const slides=track.querySelectorAll('.planslide');track.scrollLeft=slides[selectedPlan].offsetLeft-slides[0].offsetLeft});track.addEventListener('scroll',()=>{clearTimeout(scrollTimer);scrollTimer=setTimeout(()=>{const step=track.querySelector('.planslide').getBoundingClientRect().width+12;update(Math.round(track.scrollLeft/step))},100)});track.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();move(selectedPlan+(e.key==='ArrowRight'?1:-1))}})}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.id==='prev'||b.id==='next')move(selectedPlan+(b.id==='next'?1:-1));else if(b.hasAttribute('data-slide'))move(Number(b.dataset.slide));else if(b.hasAttribute('data-open')){selectedPlan=Number(b.dataset.open);tell({go:'plan'})}else if(b.dataset.session)tell({session:b.dataset.session,go:b.dataset.go});else if(b.dataset.go){if(['plans','plan','detail','workout'].includes(b.dataset.go))tell({go:b.dataset.go,exercise:b.dataset.exercise});else tell({info:'Ten mock-up obejmuje cztery wybrane ekrany. '+b.textContent.trim()+' pozostaje poza przepływem.'})}else if(b.hasAttribute('data-fill')){document.querySelector('[name=reps]').value=b.dataset.reps||'6';document.querySelector('[name=kg]').value=b.dataset.kg||'90';document.getElementById('save-status').textContent='Uzupełniono pola. Wynik czeka na zapis.'}else if(b.dataset.info)tell({info:b.dataset.info})});
const form=document.getElementById('result');if(form)form.addEventListener('submit',e=>{e.preventDefault();const reps=form.elements.reps.value.trim(),kg=form.elements.kg.value.trim();document.getElementById('save-status').textContent=(!reps||!kg)?'Wpisz wykonane powtórzenia i ciężar.':'Symulacja: zapisano '+reps+' powt. × '+kg+' kg. Brak zapisu do bazy.'});
</script>'''
def selected_frame(screen,session='a',pi=0,ei=0):
 variant='cards' if screen=='workout' else 'focus'
 html=frame(variant,screen,session,eidx=ei)
 html=html.replace('Fundament siły',plans[pi]['name'])
 if screen=='plans':
  start=html.index('<main class="scroll">');end=html.index('</main>',start)+len('</main>')
  html=html[:start]+'<main class="scroll"><div class="body">'+plans_content(pi)+'</div></main>'+html[end:]
 html=html.replace('</style>',extra_css+'</style>')
 html=html[:html.rfind('<script>')]+inner_script.replace('__NAMES__',json.dumps([p['name'] for p in plans],ensure_ascii=False)).replace('__PLAN__',str(pi))+'</body></html>'
 return html
frames={f'{s}:{d}:{p}:{i}':selected_frame(s,d,p,i) for s in ['plans','plan','detail','workout'] for d in ['a','b'] for p in range(3) for i in (range(4) if s=='detail' else [0])}
gallery='''<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Forma · wybrany kierunek</title><style>
:root{font-family:Arial,Helvetica,sans-serif;color:#1c2420;background:#e9ede7}*{box-sizing:border-box}body{margin:0}button{font:inherit;cursor:pointer;color:inherit}button:focus-visible{outline:3px solid #467d27;outline-offset:3px}header{padding:24px 28px;background:#f8faf5;border-bottom:1px solid #ccd7c7;display:flex;justify-content:space-between;align-items:center;gap:24px}h1{font-size:25px;letter-spacing:-.03em;margin:0 0 8px}header p{font-size:13px;color:#556259;margin:0;line-height:1.5;max-width:950px}.approved{padding:10px 14px;background:#d7f26d;color:#183b31;border-radius:9px;font-size:13px;font-weight:700;white-space:nowrap}.toolbar{padding:14px 28px;background:#f8faf5;display:flex;align-items:center;flex-wrap:wrap;gap:6px;border-bottom:1px solid #ccd7c7}.toolbar button{min-height:44px;padding:10px 14px;border-radius:9px;background:none;border:0;font-size:13px;font-weight:700;color:#556259}.toolbar button.on{background:#183b31;color:white}.toolbar .reset{margin-left:auto;border:1px solid #c7d2c1}.stage{display:grid;grid-template-columns:repeat(4,minmax(320px,390px));justify-content:center;gap:20px;overflow:auto;padding:26px 24px;align-items:start}.stage.single{grid-template-columns:minmax(300px,390px)}.frame-title{font-size:18px;letter-spacing:-.02em;margin:0 0 8px}.caption{font-size:12px;color:#556259;line-height:1.5;min-height:36px;margin:0 0 12px}.phone{height:846px;background:#f6f7f2;border:1px solid #9bae94;border-radius:20px;overflow:hidden}.phone iframe{height:844px;width:100%;display:block;border:0}.notes{display:flex;gap:36px;padding:24px 28px;border-top:1px solid #ccd7c7;background:#f8faf5}.notes>div{flex:1}.notes h2{font-size:17px;margin:0 0 8px}.notes p{font-size:13px;color:#556259;line-height:1.6;margin:0}.notes a{color:#183b31;text-underline-offset:3px}.toast{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);background:#183b31;color:white;border-radius:10px;max-width:600px;padding:14px 18px;font-size:13px;line-height:1.5;z-index:2}.toast[hidden]{display:none}@media(max-width:1400px){.stage{justify-content:start;grid-template-columns:repeat(4,360px)}.stage.single{justify-content:center;grid-template-columns:minmax(300px,390px)}}@media(max-width:600px){header{padding:20px 16px}.approved{display:none}.toolbar{padding:12px 16px}.stage{padding:16px;grid-template-columns:repeat(4,calc(100vw - 32px));gap:16px}.stage.single{grid-template-columns:minmax(0,1fr)}.notes{padding:22px 16px;flex-direction:column;gap:20px}h1{font-size:23px}}
</style></head><body><header><div><h1>Forma. Twój wybrany kierunek.</h1><p>Plany A z przesuwaniem lewo/prawo · Podgląd A · Szczegóły A · Zapis serii C. Sprawdź całość albo otwórz jeden ekran i przejdź przez przepływ. Dane i zapis są demonstracyjne.</p></div><span class="approved">A / A / A / C</span></header><nav class="toolbar" aria-label="Przegląd ekranów"><button data-screen="all" class="on">Wszystkie ekrany</button><button data-screen="plans">1. Plany</button><button data-screen="plan">2. Podgląd</button><button data-screen="detail">3. Szczegóły</button><button data-screen="workout">4. Zapis serii</button><button class="reset" id="reset">Wróć do początku</button></nav><main class="stage" id="stage"></main><section class="notes"><div><h2>Wiele planów</h2><p>Na ekranie Planów przesuń kartę w lewo lub w prawo. Strzałki i wskaźniki umożliwiają ten sam wybór bez gestu. Karuzela nie przesuwa się automatycznie. Pod nią są treningi wybranego planu.</p></div><div><h2>Spójny przepływ</h2><p>Otwórz plan, wybierz trening, przejdź do ćwiczenia lub rozpocznij trening. Podgląd i szczegóły zachowują układ A, a formularz serii korzysta z C. Ikony, kolory i nazwa wybranego planu pozostają spójne.</p></div><div><h2>Etap projektowania</h2><p>To połączony mock-up z trzema syntetycznymi planami. Zapis serii jest symulacją, a import i głos zachowują swoje istniejące przepływy. <a href="t14-mockupy.html">Wróć do oryginalnych opcji A/B/C</a>.</p></div></section><div class="toast" id="toast" role="status" hidden></div><script>
const FRAMES=__FRAMES__;const screens=[{id:'plans',label:'1. Plany · A',caption:'Karty planów z gestem lewo/prawo i wyborem bez gestu.'},{id:'plan',label:'2. Podgląd · A',caption:'Krótka lista i osobne serie, obciążenie oraz przerwa.'},{id:'detail',label:'3. Szczegóły · A',caption:'Podsumowanie, tabela serii, uwagi i źródło.'},{id:'workout',label:'4. Zapis serii · C',caption:'Jedna seria, wyraźny cel oraz pola wykonanego wyniku.'}];let screen='all',session='a',planIndex=0,exerciseIndex=0,timer;const stage=document.getElementById('stage');
function fill(iframe,s){iframe.srcdoc=FRAMES[s+':'+session+':'+planIndex+':'+(s==='detail'?exerciseIndex:0)]}
function render(){stage.classList.toggle('single',screen!=='all');stage.innerHTML='';screens.filter(s=>screen==='all'||s.id===screen).forEach(s=>{const section=document.createElement('section');section.innerHTML='<h2 class="frame-title">'+s.label+'</h2><p class="caption">'+s.caption+'</p><div class="phone"><iframe data-frame="'+s.id+'" sandbox="allow-scripts allow-forms" title="'+s.label+'"></iframe></div>';fill(section.querySelector('iframe'),s.id);stage.appendChild(section)});document.querySelectorAll('[data-screen]').forEach(b=>{b.classList.toggle('on',b.dataset.screen===screen);b.setAttribute('aria-pressed',b.dataset.screen===screen)})}
function info(text){const el=document.getElementById('toast');el.textContent=text;el.hidden=false;clearTimeout(timer);timer=setTimeout(()=>el.hidden=true,6500)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.screen){screen=b.dataset.screen;render()}if(b.id==='reset'){screen='all';session='a';planIndex=0;exerciseIndex=0;render()}});
window.addEventListener('message',e=>{const source=[...document.querySelectorAll('iframe')].find(f=>f.contentWindow===e.source);if(!source||!e.data?.selectedMock)return;const d=e.data;if(d.info){info(d.info);return}if(Number.isInteger(d.plan)&&d.plan>=0&&d.plan<3)planIndex=d.plan;if(d.selectPlan){document.querySelectorAll('iframe:not([data-frame=plans])').forEach(f=>fill(f,f.dataset.frame));return}if(d.session)session=d.session;if(d.exercise!==undefined)exerciseIndex=Number(d.exercise)||0;if(d.go){screen=d.go;render()}});render();
</script></body></html>'''
gallery=gallery.replace('__FRAMES__',json.dumps(frames,ensure_ascii=False).replace('</script>','<\\/script>'))
(out/'t14-selected.html').write_text(gallery)
print('Wybrany mock-up:',len(frames),'stanów;',len(gallery),'znaków')
